//! Constructed actual LocalStore metadata tests, not the real A6 graph or a
//! Root SDK grant. Genuine receipts pin catalogue DATA only.
use super::*;
use crate::{content::{self,StagedContentStore},directory::{DirectoryEntry,EntryNode,LocalDirectoryStore,PagedDirectory},store::LocalStore};
use sha2::{Digest,Sha256};
use std::{io::Cursor,time::Duration};
fn selected(id:&str)->CompilerSdkCatalogData{compiler_sdk_profiles_data().iter().find(|p|p.profile_id==id).unwrap().catalog_data()}
#[test]fn actual_a6_cas_and_functional_receipts_match_only_the_explicit_c1_data_tuple(){
 let artifact:serde_json::Value=serde_json::from_str(include_str!("fixtures/compiler_c1_artifact_a6.json")).unwrap();let cas:serde_json::Value=serde_json::from_str(include_str!("fixtures/compiler_c1_cas_a2.json")).unwrap();let functional:serde_json::Value=serde_json::from_str(include_str!("fixtures/compiler_c1_functional_a5.json")).unwrap();let c=selected(C1_PROFILE);c.validate_data().unwrap();let marker=&cas["results"][0]["marker"];
 assert_eq!(artifact["digest"],c.artifact_image.rsplit_once('@').unwrap().1);assert_eq!(cas["digest"],c.cas_image.rsplit_once('@').unwrap().1);assert_eq!(serde_json::to_value(&c.artifact_manifest).unwrap(),marker["compiler"]["artifact_manifest"]);assert_eq!(serde_json::to_value(&c.inventory).unwrap(),marker["inventory"]);assert_eq!(serde_json::to_value(&c.manifest).unwrap(),marker["roots"]["manifest"]);assert_eq!(serde_json::to_value(&c.installer_input).unwrap(),marker["roots"]["installer_input"]);
 assert_eq!(format!("{:x}",Sha256::digest(include_bytes!("fixtures/compiler_c1_source_binding.json"))),c.source_binding_sha256);assert_eq!(cas["results"][0]["outputs"]["sourceBinding"]["sha256"],c.source_binding_sha256);
 assert_eq!(artifact["componentPassed"],true);assert_eq!(cas["componentPassed"],true);assert_eq!(functional["componentPassed"],true);assert_eq!(functional["sdkRoleQualified"],false);assert_eq!(functional["guest"]["functional"]["physical_Root_Native_SDK_grant"],false);assert_eq!(functional["guest"]["functional"]["Rudder_repository_build"],false);assert_eq!(cas["productionActivation"],false);
}
#[test]fn catalogue_refuses_unknown_old_guessed_runtime_or_cross_profile_pins(){
 let a=selected(A2_PROFILE);let c=selected(C1_PROFILE);for wrong in ["rudder-linux-rust-cxx-typescript-c2","rudder-linux-rust-cxx-typescript-c1 ","rudder-linux-c1-guessed"]{let mut x=c.clone();x.profile_id=wrong.into();assert!(x.validate_data().is_err());}
 for field in 0..7{let mut x=c.clone();match field{0=>x.artifact_image=a.artifact_image.clone(),1=>x.cas_image=a.cas_image.clone(),2=>x.artifact_manifest=a.artifact_manifest.clone(),3=>x.inventory=a.inventory.clone(),4=>x.manifest=a.manifest.clone(),5=>x.installer_input=a.installer_input.clone(),_=>x.source_binding_sha256=a.source_binding_sha256.clone()};assert!(x.validate_data().is_err());}
 let mut x=c.clone();x.cas_image=x.artifact_image.clone();assert!(x.validate_data().is_err());let mut x=c.clone();x.inventory.size_bytes+=1;assert!(x.validate_data().is_err());let mut x=c;x.installer_input.kind=ObjectKind::Blob;assert!(x.validate_data().is_err());
}
#[test]fn a2_catalogue_overlay_and_five_tools_remain_exact_with_no_c1_inference(){
 let a=selected(A2_PROFILE);a.validate_data().unwrap();assert_eq!(a.artifact_manifest.digest,ARTIFACT_MANIFEST);assert_eq!(a.artifact_manifest.size_bytes,190431);let d=a.profile_data().unwrap();assert_eq!(d.artifact_directory,"/rudder-compiler-v1");assert_eq!(d.cas_directory,"/var/lib/rudder-compiler-cas-v1");assert_eq!((d.source_mount,d.guest_mount),(SDK_SOURCE,SDK_GUEST));assert_eq!(d.tools.iter().map(|p|p.name).collect::<Vec<_>>(),["buck2","rustc","node","typescript","python"]);
 let c=selected(C1_PROFILE);let d=c.profile_data().unwrap();assert_eq!(d.artifact_directory,"/rudder-compiler-c1");assert_eq!(d.cas_directory,"/var/lib/rudder-compiler-c1-cas-v1");assert_eq!((d.source_mount,d.guest_mount),(SDK_SOURCE,SDK_GUEST));assert_eq!(d.tools.len(),9);for (name,path)in[("cargo","prepared/tools/rust/bin/cargo"),("cc","prepared/usr/bin/cc"),("cxx","prepared/usr/bin/c++"),("ar","prepared/usr/bin/ar")]{assert!(d.tools.iter().any(|s|s.name==name&&s.relative_path==path));}
}
type Row=(ObjectRef,u64,u32,String);
fn tree(store:&LocalStore,stage:&str,rows:&BTreeMap<String,Row>,prefix:&str)->ObjectRef{
 let mut names=BTreeMap::new();for path in rows.keys(){let Some(rest)=path.strip_prefix(prefix)else{continue};if let Some((name,_))=rest.split_once('/'){names.entry(name.to_owned()).or_insert(None);}else{names.insert(rest.to_owned(),Some(path));}}
 let adapter=LocalDirectoryStore::new(store,stage);let mut entries=Vec::new();for(name,file)in names{let node=if let Some(path)=file{let(object,logical_size,mode,_)=&rows[path];EntryNode::File{object:object.clone(),logical_size:*logical_size,mode:*mode}}else{EntryNode::Directory{object:tree(store,stage,rows,&format!("{prefix}{name}/"))}};entries.push(DirectoryEntry::new(name.as_bytes(),node).unwrap());}PagedDirectory::new(&adapter).build(0o555,entries).unwrap()
}
fn fixture(profile:&CompilerSdkCatalogData,script:&[u8])->(tempfile::TempDir,LocalStore,CompilerSdkSemanticData,Vec<CompilerSdkToolMemberData>,ObjectRef){
 let temp=tempfile::tempdir().unwrap();let store=LocalStore::open(temp.path().join("cas")).unwrap();let stage=store.begin_staging(Duration::from_secs(120)).unwrap();let mut rows=BTreeMap::new();let descriptor=profile.profile_data().unwrap();
 let mut paths=descriptor.tools.iter().map(|s|s.relative_path).collect::<Vec<_>>();paths.extend(descriptor.tools.iter().filter_map(|s|s.compiler_entrypoint));paths.sort();paths.dedup();
 for path in paths {let bytes=if path=="prepared/tools/typescript/lib/tsc.js"{script.to_vec()}else if path=="prepared/tools/rust/bin/rustc"{vec![0x43;content::CHUNK_BYTES+19]}else{format!("constructed local metadata:{path}").into_bytes()};let object=content::import_file(&StagedContentStore::new(&store,&stage.id).unwrap(),&mut Cursor::new(&bytes)).unwrap();rows.insert(path.to_owned(),(object,bytes.len()as u64,if path.ends_with("/tsc.js"){0o444}else{0o555},format!("{:x}",Sha256::digest(&bytes))));}
 let root=tree(&store,&stage.id,&rows,"");store.publish(&stage.id,"constructed-sdk-metadata",&root).unwrap();let dirs=LocalDirectoryStore::read_only(&store);let prepared=match PagedDirectory::new(&dirs).lookup(&root,b"prepared").unwrap().unwrap().node{EntryNode::Directory{object}=>object,_=>panic!("prepared fixture")};let buck=&rows["buck2"];let(semantic,_)=CompilerSdkSemanticData::from_members_data(prepared,buck.0.clone(),buck.1,buck.2).unwrap();let members=descriptor.tools.iter().map(|spec|{let(object,size,mode,sha)=&rows[spec.relative_path];CompilerSdkToolMemberData{name:spec.name.into(),relative_path:spec.relative_path.into(),content:object.clone(),logical_size:*size,mode:*mode,raw_sha256:sha.clone()}}).collect();(temp,store,semantic,members,root)
}
#[test]fn constructed_actual_local_metadata_derives_complete_c1_identities_without_real_a6_owner(){
 let c=selected(C1_PROFILE);let(_tmp,store,semantic,members,root)=fixture(&c,b"constructed TypeScript script\n");assert_ne!(root,c.installer_input);let tools=c.toolchains_from_members_data(&semantic,&members).unwrap();assert_eq!(tools.len(),9);assert_eq!(tools["rustc"].executable.kind,ObjectKind::File);assert_eq!(tools["buck2"].executable,semantic.buck2);CompilerSdkMountData{catalog:c.clone(),semantic:semantic.clone(),floor:super::super::runtime_image::RuntimeFdData{device:1,inode:2,mount_id:3,directory:true},toolchains:tools.clone()}.validate_data().unwrap();
 for(name,identity)in tools {let member=members.iter().find(|m|m.name==name).unwrap();assert_eq!(identity.closure,semantic.directory);assert_eq!(identity.version,semantic.directory.digest);assert_eq!(identity.executable,member.content);assert_eq!(identity.configuration["executable_raw_sha256"],member.raw_sha256);assert_eq!(identity.configuration.len(),if name=="typescript"{2}else{1});}
 assert!(store.retention().unwrap().pins.values().any(|r|r==&root)); // constructed local pin, not a foreign A6 pin.
}
#[test]fn selected_member_path_mode_size_duplicate_and_missing_tool_fail_closed_as_data(){
 let c=selected(C1_PROFILE);let(_tmp,_store,semantic,members,_)=fixture(&c,b"script");for case in 0..6{let mut bad=members.clone();match case{0=>{bad.pop();},1=>bad[0].relative_path="../../foreign".into(),2=>bad[0].mode=0o755,3=>bad[0].logical_size=0,4=>bad[0].raw_sha256="A".repeat(64),_=>bad[1]=bad[0].clone()};assert!(c.toolchains_from_members_data(&semantic,&bad).is_err());}
}
#[test]fn complete_prepared_script_content_changes_semantic_key_even_with_same_node_program(){
 let c=selected(C1_PROFILE);let(_a,_s,a,members_a,_)=fixture(&c,b"one");let(_b,_s,b,members_b,_)=fixture(&c,b"two");let a_tools=c.toolchains_from_members_data(&a,&members_a).unwrap();let b_tools=c.toolchains_from_members_data(&b,&members_b).unwrap();assert_eq!(a_tools["typescript"].executable,b_tools["typescript"].executable);assert_ne!(a_tools["typescript"].closure,b_tools["typescript"].closure);assert_ne!(a_tools["typescript"].version,b_tools["typescript"].version);
}
